import {registerPartTwo} from './part-two.js';
import {partOneActivities,partOneRules} from './part-one.js';
import {extraActivities,missingBookPages} from './audit.js';
import {themes} from './curriculum.js';
import {lessons,words,supplementIds,foundationIds,wordSupplements} from './data.js';
import {activities,numberTasks} from './activities.js';
import {bookPages} from './book-pages.js';
for(const t of themes){activities[t.id].push(...extraActivities[t.id],...partOneActivities[t.id]);t.rules.push(...(partOneRules[t.id]||[]));if(t.id==='welcome')t.ids=[0,1,2,3,4,7,8];if(t.id==='school')t.ids=[5,6,9,10,11,12];t.ids.push(...(supplementIds[t.id]||[]));}
for(const t of themes)t.part=1;
registerPartTwo(themes,lessons,words,activities,bookPages);
let activePart=1;
const visibleThemes=()=>themes.filter(t=>t.part===activePart);
const scopedLessons=()=>[...new Set([...visibleThemes().flatMap(t=>t.ids),...foundationIds])].map(id=>lessons[id]);
const bookLimit=()=>activePart===2?100:102;
const bookDir=()=>activePart===2?'book2':'book';
const pageKey=()=>activePart===2?`2:${bookPage}`:String(bookPage);
themes[0].chapter='Welcome back! · с. 4–8 · счёт 1–20';
const $=id=>document.getElementById(id), main=$('main'), byId=Object.fromEntries(words.map(w=>[w.id,w])), KEY='english-islands-v1';
const fresh=()=>({version:1,xp:0,done:{},stats:{},voice:'',session:null,days:[]});
let activeTheme=null,themeTab='study',quizState=null,bookPage=4;
let db=fresh(),storageOK=true,view='map',filter='seen',voices=[],utterance=null,speechToken=0,toastTimer=0;
try{const raw=JSON.parse(localStorage.getItem(KEY)||'null');if(raw&&raw.version===1&&typeof raw.done==='object'&&typeof raw.stats==='object'&&Number.isFinite(raw.xp)){db={...fresh(),...raw};if(db.session&&(!Array.isArray(db.session.queue)||db.session.queue.some(q=>!byId[q.id])))db.session=null;}}catch{storageOK=false;}
activePart=db.part===2?2:1;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const shuffle=a=>{const b=[...a];for(let i=b.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]];}return b;};
function save(){db.part=activePart;try{localStorage.setItem(KEY,JSON.stringify(db));storageOK=true;}catch{storageOK=false;toast('Прогресс сейчас не сохраняется. Проверь свободное место и настройки браузера.');}syncTop();}
function syncTop(){document.querySelector('.book-tag').textContent='Spotlight 3 · Часть '+activePart;document.querySelector('.edition').textContent='SPOTLIGHT 3 · ЧАСТЬ '+activePart;$('xp').textContent=db.xp;$('reviewBadge').textContent=dueWords().length;}
function stat(id){return db.stats[id]??={seen:0,correct:0,errors:0,streak:0,due:0,modes:[],last:0};}
function dueWords(){return words.filter(w=>db.stats[w.id]?.seen&&(db.stats[w.id].due<=Date.now()||db.stats[w.id].streak===0)).sort((a,b)=>{const sa=db.stats[a.id],sb=db.stats[b.id];return (sb.errors-sb.correct)-(sa.errors-sa.correct)||sa.due-sb.due;});}
const completed=()=>scopedLessons().filter(l=>db.done[l.id]>0).length;
const nextLesson=()=>scopedLessons().find(l=>!db.done[l.id])||scopedLessons()[0];
function toast(text){$('toast').textContent=text;$('toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').style.display='none',3800);}
function stopSpeech(){speechToken++;window.speechSynthesis?.cancel();document.querySelectorAll('.speaking').forEach(b=>b.classList.remove('speaking'));}
function getVoices(){voices=(window.speechSynthesis?.getVoices()||[]).filter(v=>/^en([-_]|$)/i.test(v.lang));if(view==='parent')populateVoices();}
window.speechSynthesis?.addEventListener('voiceschanged',getVoices);getVoices();
function speak(id,slow=false,button=null,onStarted=null){const word=byId[id];if(!word)return;stopSpeech();const token=speechToken;if(!window.speechSynthesis||!window.SpeechSynthesisUtterance){audioError();return;}
getVoices();const voice=voices.find(v=>v.voiceURI===db.voice)||voices.find(v=>v.lang==='en-GB')||voices.find(v=>v.lang==='en-US')||voices[0];utterance=new SpeechSynthesisUtterance(word.speech);utterance.lang=voice?.lang||'en-GB';if(voice)utterance.voice=voice;utterance.rate=slow?.65:.85;utterance.pitch=1;utterance.volume=1;
let began=false;const timeout=setTimeout(()=>{if(!began&&token===speechToken)audioError();},5000);
utterance.onstart=()=>{if(token!==speechToken)return;onStarted?.();began=true;clearTimeout(timeout);button?.classList.add('speaking');if(token!==speechToken)return;if(db.session&&view==='lesson'){let q=db.session.queue[db.session.index];if(q?.id===id){q.heard=true;save();document.querySelectorAll('.choice').forEach(b=>{if(!q.answered)b.disabled=false;});$('audio-error')?.setAttribute('hidden','');}}};
utterance.onend=()=>{clearTimeout(timeout);button?.classList.remove('speaking');};utterance.onerror=e=>{clearTimeout(timeout);button?.classList.remove('speaking');if(token===speechToken&&!['interrupted','canceled'].includes(e.error))audioError();};
try{window.speechSynthesis.resume();window.speechSynthesis.speak(utterance);}catch{audioError();}}
function audioError(){const error=$('audio-error');if(error)error.hidden=false;else toast('Озвучка недоступна. Проверь громкость, подключение и английский голос в настройках телефона.');}
function header(label,title,subtitle){return `<div class="breadcrumb">${label}</div><h1>${title}</h1><p class="sub">${subtitle}</p>`;}
function renderMap(){const next=nextLesson(),done=completed(),seen=scopedLessons().flatMap(l=>l.words).filter(w=>db.stats[w.id]?.seen).length,stars=scopedLessons().reduce((a,l)=>a+(db.done[l.id]||0),0);
main.innerHTML=`<div class="filters part-switch" role="group" aria-label="Часть учебника"><button class="chip ${activePart===1?'active':''}" data-part="1">Часть 1</button><button class="chip ${activePart===2?'active':''}" data-part="2">Часть 2</button></div>`+header('SPOTLIGHT 3 · ЧАСТЬ '+activePart,'Часть '+activePart+' · острова английского','Открывай острова, учи слова и помогай дракону расти.')+`<section class="welcome"><div class="welcome-copy"><span class="tag">ПРИКЛЮЧЕНИЕ НАЧИНАЕТСЯ</span><h2>${db.session?'Продолжим путешествие?':done?'Следующий остров ждёт!':'Первый остров ждёт!'}</h2><p>Я Драко! Давай слушать английские слова и открывать новое вместе.</p><button class="btn" data-action="continue">${db.session?'Продолжить занятие':done?'Продолжить путь':'Начать приключение'} &nbsp;→</button></div><img src="dragon.png" alt="Дружелюбный голубой дракон с книгой на летающем острове"></section><section class="stats" aria-label="Прогресс"><div class="stat"><span>⚑</span><div><strong>${done}<small> / ${scopedLessons().length}</small></strong><small>занятий пройдено</small></div></div><div class="stat"><span>▤</span><div><strong>${seen}</strong><small>слов в коллекции</small></div></div><div class="stat"><span>★</span><div><strong>${stars}</strong><small>звёзд собрано</small></div></div></section><div class="section-heading"><h2>Часть ${activePart} · все темы и задания</h2><small>3–5 слов за уровень</small></div>`;
for(const theme of visibleThemes()){const finished=theme.ids.filter(id=>db.done[id]).length;const result=db.topicResults?.[theme.id];main.insertAdjacentHTML('beforeend',`<section class="topic-map-card"><div class="topic-map-head"><span class="lesson-icon">${theme.icon}</span><div><h2>${esc(theme.title)}</h2><small>${esc(theme.chapter)}</small></div><button class="btn" data-topic="${theme.id}">Изучить тему</button></div><p>${theme.ids.length} занятий со словами · ${theme.rules.length} памяток · ${theme.quiz.length} заданий по правилам · ${activities[theme.id].length} заданий для закрепления${result?` · последний результат: ${result.correct}/${result.total}`:''}</p><div class="lesson-grid">${theme.ids.map(id=>{const l=lessons[id];return `<button class="lesson ${db.done[id]?'done':''}" data-lesson="${id}"><div class="lesson-top"><span class="lesson-icon">${l.icon}</span><span class="lesson-num">${String(id+1).padStart(2,'0')}</span></div><strong>${esc(l.title)}</strong><small>${l.words.length} слов · около 5 минут</small>${db.done[id]?`<span class="stars">${'★'.repeat(db.done[id])}</span>`:''}</button>`;}).join('')}</div><small class="muted-note">Слова: ${finished} / ${theme.ids.length} занятий пройдено</small></section>`);}
main.insertAdjacentHTML('beforeend',`<section class="settings-card"><h2>Часть ${activePart} · учебник</h2><p>${activePart===1?'Welcome back!, модули 1–4, дополнительные чтение, письмо, диалоги, словарь и фонетика.':'Модули 5–8, счёт 20–100, неправильные глаголы, время и даты, День матери, дополнительные чтение, письмо и диалоги.'}</p><button class="btn secondary" data-topic="${visibleThemes()[0].id}" data-open-book="1">Открыть страницы части ${activePart}</button><p class="muted-note">Задания тренажёра составлены по присланному учебнику. Озвучка синтезированная. Для оригинальных песен и аудиозаданий нужны записи аудиоприложения. Проекты и ответы к оригинальным упражнениям проверяет взрослый. ${activePart===1?'На с. 30 часть картинок отсутствует в исходном PDF; добавлены текстовые тренировки.':''} Прогресс хранится в этом браузере.</p></section>`);}
function themeWords(){const list=activeTheme.ids.flatMap(id=>lessons[id].words);for(const [en] of wordSupplements[activeTheme.id]||[]){const w=words.find(w=>w.en.toLowerCase()===en.toLowerCase());if(w&&!list.some(x=>x.en.toLowerCase()===en.toLowerCase()))list.push(w);}return list;}
function renderTheme(){const t=activeTheme;if(!t){visit('map');return;}main.innerHTML=`<button class="chip" data-view="map">Часть ${activePart} · карта островов</button>`+header(esc(t.chapter),`${t.icon} ${esc(t.title)}`,'Изучи, послушай, повтори и проверь себя.')+`<div class="filters" role="group" aria-label="Разделы темы">${[['study','Изучить'],['words','Слова и звук'],['practice','Правила: проверка'],['sentences','Строим предложения'],...((t.id==='welcome'||t.numberTasks)?[['numbers',t.numberTasks?'Счёт 20–100':'Счёт 1–20']]:[]),['helpers','Слова-помощники'],['book','Учебник · Часть '+t.part]].map(([id,label])=>`<button class="chip ${themeTab===id?'active':''}" data-topic-tab="${id}">${label}</button>`).join('')}</div><div id="topic-content"></div>`;
const content=$('topic-content');if(themeTab==='study'){content.innerHTML=t.rules.map((r,i)=>`<section class="settings-card"><h2>${esc(r.title)}</h2><p>${esc(r.text)}</p><div class="example"><strong lang="en">${esc(r.en)}</strong><p>${esc(r.ru)}</p><button class="audio-btn" data-example="${i}">Слушать пример</button><button class="audio-btn" data-example="${i}" data-example-slow="1">Медленнее</button></div></section>`).join('')+`<button class="btn" data-topic-tab="practice">Проверить себя</button>`;}else if(themeTab==='words'){content.innerHTML=`<p class="sub">Слушай слово, повторяй вслух. Для тренировки перевода и слуха выбери занятие.</p><div class="word-list">${themeWords().map(wordRow).join('')}</div><div class="filters">${t.ids.map(id=>`<button class="chip" data-lesson="${id}">${esc(lessons[id].title)}</button>`).join('')}</div>`;}else if(themeTab==='helpers'){content.innerHTML=`<p class="sub">Эти слова соединяют предметы и действия в предложения. Учим их вместе с примерами из памяток.</p><div class="word-list">${foundationIds.flatMap(id=>lessons[id].words).map(wordRow).join('')}</div><div class="filters">${foundationIds.map(id=>`<button class="chip" data-lesson="${id}">${esc(lessons[id].title)}</button>`).join('')}</div>`;}else if(themeTab==='book')renderBook();else renderQuiz();}
function speakExample(index,slow,button){const r=activeTheme?.rules[index];if(!r)return;const id='topic-example';byId[id]={speech:r.en};speak(id,slow,button);}
function currentTasks(){return themeTab==='numbers'?(activeTheme.numberTasks||numberTasks):themeTab==='sentences'?activities[activeTheme.id]:activeTheme.quiz;}
function normalized(s,keepCase=false){let x=String(s).trim().replace(/[’‘]/g,"'");if(!keepCase)x=x.toLowerCase();const contractions={"i'm":"i am","you're":"you are","he's":"he is","she's":"she is","it's":"it is","we're":"we are","they're":"they are","i've":"i have","you've":"you have","we've":"we have","they've":"they have","don't":"do not","doesn't":"does not","didn't":"did not","wasn't":"was not","weren't":"were not","haven't":"have not","hasn't":"has not","can't":"cannot","what's":"what is","i'd":"i would","you'd":"you would","he'd":"he would","she'd":"she would"};for(const [k,v] of Object.entries(contractions))x=x.split(k).join(v);x=x.replace(/\b(is|are|was|were)n\'t\b/g,"$1 not");return x.replace(/[.,?!:;]/g,'').replace(/\s+/g,' ').trim();}
function submitTask(selected,self=false){const state=quizState,bank=currentTasks(),q=bank[state.index];if(state.answers[state.index])return;if(!selected.trim()){toast('Сначала напиши ответ или собери предложение.');return;}if(q.kind==='listenNumber'&&!state.heard&&!state.textMode){toast('Сначала послушай число.');return;}const candidates=[selected,selected.replace(/\b(he|she|it)[’\']s\s+got\b/gi,"$1 has got")];const right=self?null:[q.answer,...(q.alternatives||[])].some(a=>candidates.some(s=>normalized(s,!!q.caseSensitive)===normalized(a,!!q.caseSensitive)));state.answers.push({index:state.index,selected,right,self});db.practiceAnswers??={};db.practiceAnswers[`${state.topic}:${state.index}`]={selected,right,self};save();if(right){state.correct++;db.xp+=5;save();}renderQuiz();}
function renderQuiz(){const c=$('topic-content'),t=activeTheme,bank=currentTasks(),key=`${t.id}:${themeTab}`;if(!quizState||quizState.topic!==key)quizState=db.practiceSessions?.[key]||{topic:key,index:0,correct:0,answers:[]};const state=quizState;db.practiceSessions??={};db.practiceSessions[key]=state;save();if(state.index>=bank.length){const checked=state.answers.filter(a=>!a.self),last={correct:state.correct,total:checked.length,creative:state.answers.filter(a=>a.self).length};db.topicResults??={};db.topicResults[key]=last;if(themeTab==='practice')db.topicResults[t.id]=last;save();c.innerHTML=`<section class="settings-card"><h2>Тренировка завершена!</h2><p>Проверяемые ответы: <strong>${last.correct} из ${last.total}</strong>. ${last.creative?`Творческих работ сохранено: ${last.creative}.`:''}</p><p>${last.correct===last.total?'Все проверяемые ответы верные!':'Повтори задания, в которых были ошибки.'}</p>${state.answers.filter(a=>a.right===false).map(a=>{const q=bank[a.index];return `<div class="feedback warm"><strong>${esc(q.prompt)}</strong><p>Твой ответ: ${esc(a.selected)}<br>Образец: ${esc(q.answer)}</p><p>${esc(q.why||'')}</p></div>`;}).join('')}<div class="filters"><button class="btn" data-topic-retry="1">Ещё раз</button><button class="btn secondary" data-topic-tab="study">Повторить правила</button></div></section>`;return;}
const q=bank[state.index],a=state.answers[state.index];let task='';if(['build','write','free','listenNumber'].includes(q.kind)){if(q.kind==='build'){if(!state.tokens){state.tokens=shuffle(q.tokens.map((word,id)=>({word,id})));state.picked=[];}task=`<p class="task-help">Нажимай на слова по порядку. Нажми на выбранное слово, чтобы вернуть его.</p><div class="sentence-answer" aria-label="Собранное предложение">${state.picked.map(id=>{const token=state.tokens.find(t=>t.id===id);return `<button class="chip" data-unpick="${id}" ${a?'disabled':''}>${esc(token.word)}</button>`;}).join('')||'<span>Здесь появится предложение</span>'}</div><div class="word-tiles">${state.tokens.filter(token=>!state.picked.includes(token.id)).map(token=>`<button class="chip" data-pick="${token.id}" ${a?'disabled':''}>${esc(token.word)}</button>`).join('')}</div>${a?'':'<button class="btn" data-check-build="1">Проверить предложение</button>'}`;}else{const isAudio=q.kind==='listenNumber';if(isAudio)task+=`<div class="audio-controls"><button class="audio-btn" data-task-audio="1">Послушать число</button><button class="audio-btn" data-task-audio="slow">Медленнее</button></div><div id="audio-error" class="audio-error" hidden>Озвучка недоступна. Проверь голос устройства или переключись на чтение.<button class="chip" data-number-text="1">Продолжить с текстом</button></div>${state.textMode?`<p lang="en"><strong>${esc(q.speech)}</strong> · проверка чтения</p>`:''}`;task+=`<form id="written-task"><label for="written-answer">${q.kind==='free'?'Твоя работа':isAudio?'Число цифрами':'Твой ответ по-английски'}</label>${q.kind==='free'?`<textarea id="written-answer" rows="6" ${a?'disabled':''}>${esc(a?.selected||state.draft||'')}</textarea>`:`<input id="written-answer" type="text" lang="en" autocomplete="off" autocapitalize="none" spellcheck="false" ${isAudio?'inputmode="numeric"':''} value="${esc(a?.selected||state.draft||'')}" ${a?'disabled':''}>`}${a?'':`<button class="btn" type="submit" id="written-check" ${isAudio&&!state.heard&&!state.textMode?'disabled':''}>${q.kind==='free'?'Сохранить и сверить с образцом':'Проверить ответ'}</button>`}</form>`;}}else{if(!state.options)state.options=shuffle(q.options);task=`${q.text?`<div class="reading-text" lang="en">${esc(q.text)}<button class="audio-btn" data-reading-audio="1">Послушать текст</button></div>`:''}<div class="choices">${state.options.map((option,i)=>`<button class="choice ${a?(option===q.answer?'correct':option===a.selected?'wrong':''):''}" data-topic-answer="${i}" ${a?'disabled':''}>${esc(option)}</button>`).join('')}</div>`;}
c.innerHTML=`<section class="settings-card"><div class="eyebrow">${themeTab==='numbers'?'СЧЁТ ДО 20':themeTab==='sentences'?'СТРОИМ И ПИШЕМ':'ПРОВЕРЯЕМ ПРАВИЛА'} · ${state.index+1} / ${bank.length}</div><h2>${esc(q.prompt)}</h2>${q.image?`<details><summary>Открыть страницу для задания</summary><img class="book-scan" src="${esc(q.image)}" alt="Страница учебника к заданию"></details>`:''}${task}${a?`<div class="feedback ${a.right===false?'warm':''}" role="status"><strong>${a.self?'Работа сохранена — проверь по памятке':a.right?'Верно! +5 XP':'Посмотри образец'}</strong><p>${esc(q.why||q.guide||'')}</p><p>${a.self?'Возможный вариант':'Образец'}: <span lang="en">${esc(q.answer)}</span></p><button class="audio-btn" data-answer-audio="1">Послушать образец</button>${a.self?'<p>В такой работе возможны разные ответы. Имена, цвета и личные предпочтения могут отличаться. Попроси взрослого проверить смысл и грамматику.</p>':''}</div><button class="btn" data-topic-next="1">${state.index===bank.length-1?'Посмотреть результат':'Следующее задание'}</button>`:''}</section>`;}
function trainingSpeech(text,button,slow=false,callback=null){byId['training-speech']={speech:text};speak('training-speech',slow,button,callback);}
function renderBook(){const c=$('topic-content'),pages=bookPages[activeTheme.id],page=Math.max(1,Math.min(bookLimit(),bookPage));bookPage=page;const saved=db.notebook?.[pageKey()]||{};c.innerHTML=`<section class="settings-card"><h2>Часть ${activePart} · задания учебника</h2><p>Выбери страницу и выполни задания прямо под ней. Здесь доступны страницы части ${activePart}: тексты, диалоги, песни, проекты и упражнения. Все ${bookLimit()} пронумерованных страниц доступны.</p><div class="filters"><label for="book-page">Страница</label><select id="book-page">${Array.from({length:bookLimit()},(_,i)=>i+1).map(n=>`<option value="${n}" ${n===page?'selected':''}>${n}${pages.includes(n)?' · эта тема':''}</option>`).join('')}</select><button class="chip" data-book-step="-1" ${page===1?'disabled':''}>Предыдущая</button><button class="chip" data-book-step="1" ${page===bookLimit()?'disabled':''}>Следующая</button></div><details><summary>Страницы этой темы</summary><div class="filters">${pages.map(n=>`<button class="chip" data-book-page="${n}">${n}</button>`).join('')}</div></details>${missingBookPages.includes(page)?`<div class="feedback warm"><strong>Изображение страницы ${page} недоступно.</strong><p>Открой эту страницу в своём учебнике. Задания можно выполнить и сохранить ниже. Для закрепления темы доступны упражнения тренажёра.</p></div>`:`<a href="${bookDir()}/${page}.webp" target="_blank" rel="noopener">Открыть страницу крупно</a><img class="book-scan" src="${bookDir()}/${page}.webp" alt="Страница ${page} учебника Spotlight 3, часть ${activePart}">`}<p class="muted-note">Для заданий со значком наушников нужны записи аудиоприложения. Озвучка слов и примеров тренажёра доступна в других разделах.</p>${activePart===1&&page===30?`<div class="feedback warm"><strong>Особенность исходного PDF</strong><p>Часть картинок на этой странице отсутствует в присланном файле. Открой «Строим предложения» на семейном острове: там есть текстовая тренировка одного и нескольких предметов.</p></div>`:''}<h3>Моя работа · страница ${page}</h3><p>Укажи номер задания. Для диалога запиши реплики, для письма — текст. Рисунки и проекты выполни на бумаге, здесь сохрани подписи. Ответы сохраняются на этом устройстве.</p><label for="exercise-number">Номер задания</label><input id="exercise-number" value="${esc(saved.exercise||'1')}" maxlength="30"><label for="book-answer">Мой ответ</label><textarea id="book-answer" rows="7">${esc(saved.text||'')}</textarea><div class="filters"><button class="btn" data-book-save="1">Сохранить ответ</button><button class="btn secondary" data-book-read="1">Послушать мой текст</button></div><p id="book-save-status" role="status"></p><p class="muted-note">Ответы к оригинальным заданиям не проверяются автоматически. Сверь их с учителем или взрослым. Автоматическая проверка работает в разделах «Строим предложения», «Правила» и «Счёт».</p>${Object.entries(db.bookAnswers||{}).filter(([k])=>k.startsWith(pageKey()+':')).map(([key,v])=>`<details><summary>Задание ${esc(v.exercise)} · сохранено</summary><p class="saved-work">${esc(v.text)}</p></details>`).join('')}</section>`;}
function visit(next){if(view==='lesson'&&next!=='lesson')checkpoint();stopSpeech();view=next;document.body.classList.toggle('session-active',next==='lesson');document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===next));if(next==='map')renderMap();if(next==='review')renderReview();if(next==='dictionary')renderDictionary();if(next==='parent')renderParent();if(next==='lesson')renderTask();if(next==='topic')renderTheme();window.scrollTo({top:0,behavior:'instant'});syncTop();}
function renderReview(){const due=dueWords(),seen=words.filter(w=>db.stats[w.id]?.seen);main.innerHTML=header('КОСТЁР ВОСПОМИНАНИЙ','Закрепим знакомое','Слова с ошибками возвращаются чаще. Повторяй в своём темпе.');if(!seen.length){main.insertAdjacentHTML('beforeend',`<div class="empty"><span>🌱</span><h2>Пока здесь тихо</h2><p>Пройди первый остров — здесь появятся слова для повторения.</p><button class="btn" data-view="map">На первый остров</button></div>`);return;}main.insertAdjacentHTML('beforeend',`<section class="settings-card"><h2>${due.length?`${due.length} слов ждут встречи`:'Сегодня всё повторено!'}</h2><p>${due.length?'Начнём со слов, которые пока путаются. В одной тренировке — до 5 слов.':'Можно ещё раз потренироваться со знакомыми словами.'}</p><button class="btn" data-action="review">Повторить 5 слов &nbsp;↻</button></section><div class="word-list">${(due.length?due:seen).slice(0,20).map(wordRow).join('')}</div>`);}
function wordRow(w){return `<div class="word-row"><span class="emoji" aria-hidden="true">${w.icon}</span><div><strong lang="en">${esc(w.en)}</strong><small>${esc(w.ru)}</small></div><button data-speak="${w.id}" aria-label="Послушать ${esc(w.en)}">◖))</button></div>`;}
function renderDictionary(){const selected=filter==='all'?words:filter==='hard'?words.filter(w=>db.stats[w.id]?.seen&&db.stats[w.id].streak<2):words.filter(w=>db.stats[w.id]?.seen);main.innerHTML=header('ТВОЯ КОЛЛЕКЦИЯ','Мои слова','Нажми на динамик. Послушай и повтори вслух.')+`<div class="filters">${[['seen','Знакомые'],['hard','Потренировать'],['all','Все слова']].map(([id,name])=>`<button data-filter="${id}" class="chip ${filter===id?'active':''}">${name}</button>`).join('')}</div>${selected.length?`<div class="word-list">${selected.map(wordRow).join('')}</div>`:'<div class="empty"><span>📚</span><p>Слова появятся после первого знакомства на острове.</p><button class="btn" data-view="map">Открыть карту</button></div>'}`;}
function renderParent(){const seen=words.filter(w=>db.stats[w.id]?.seen),hard=seen.filter(w=>db.stats[w.id].streak<2);main.innerHTML=header('ПОДДЕРЖКА МАЛЕНЬКОГО ИССЛЕДОВАТЕЛЯ','Для родителей','Короткие занятия, понятные задания и повторение.')+`<div class="summary"><div><strong>${completed()} / ${scopedLessons().length}</strong><span>завершённых уровней</span></div><div><strong>${hard.length}</strong><span>слов стоит потренировать</span></div></div><section class="settings-card"><h2>Сначала проверьте звук</h2><p>Игра использует английский голос устройства. Предпочтение — британскому произношению. Можно выбрать другой английский голос.</p><label for="voice">Голос для английских слов</label><select id="voice"></select><button class="btn secondary" data-speak="0-0">◖)) Проверить: Hello</button><div id="audio-error" class="audio-error" hidden>Не удалось включить озвучку. Проверьте громкость и английский голос в настройках синтеза речи телефона. Попробуйте открыть игру в Chrome или Safari.</div></section><section class="settings-card"><h2>Как играть с пользой</h2><ul><li>Начните с одного уровня: 3–5 слов, без ограничения по времени.</li><li>Попросите ребёнка сначала послушать, затем повторить вслух.</li><li>В заданиях «Вспомни сам» ребёнок сверяет себя с образцом. Игра не записывает голос и не оценивает произношение автоматически.</li><li>После ошибки показывается правильный ответ, а слово возвращается в конце занятия.</li><li>Повторение запланировано через 1, 3 и 7 дней по результатам ответов. Сложные слова доступны сразу.</li><li>Прогресс хранится только в этом браузере на этом устройстве. При очистке данных он удалится.</li></ul></section><section class="settings-card"><h2>Две части учебника</h2><p>Выбери «Часть 1» или «Часть 2» на карте. Первая часть: знакомство, школа, семья, еда, игрушки, комната, выходные и праздники. Вторая часть: животные, неправильные глаголы, дом, действия сейчас, распорядок дня, календарь, письмо и День матери.</p><p>На островах есть памятки, слова с озвучкой и задания на предложения. Счёт 1–20 находится на первом острове части 1, счёт 20–100 — на острове животных части 2. Во вкладке «Учебник» доступны оригинальные страницы и сохранение ответов. Автоматическая проверка работает в упражнениях тренажёра; открытые работы сверяются с образцом и взрослым.</p><p>Озвучка использует голос устройства. Оригинальные аудиозаписи учебника здесь не воспроизводятся.</p></section>${hard.length?`<h2>Повторите вместе</h2><div class="word-list">${hard.map(wordRow).join('')}</div>`:''}`;populateVoices();}
function populateVoices(){const select=$('voice');if(!select)return;select.innerHTML='<option value="">Автоматически · английский</option>'+voices.map(v=>`<option value="${esc(v.voiceURI)}">${esc(v.name)} (${esc(v.lang)})</option>`).join('');select.value=db.voice;select.onchange=()=>{db.voice=select.value;save();};}
function buildQueue(list,review=false){const learn=review?[]:list.map(w=>({id:w.id,mode:'learn'}));const tasks=shuffle(list.flatMap(w=>[{id:w.id,mode:'translate'},{id:w.id,mode:'listen'}]));return [...learn,...tasks,...shuffle(list).slice(0,2).map(w=>({id:w.id,mode:'recall'}))];}
function begin(id,review=false){if(db.session){const current=themes.find(t=>t.ids.includes(db.session.lesson));if(current)activePart=current.part;toast('У тебя есть незавершённое занятие. Сначала продолжим его.');visit('lesson');return;}const l=lessons[id];const candidates=dueWords(),list=review?(candidates.length?candidates:shuffle(words.filter(w=>db.stats[w.id]?.seen))).slice(0,5):l.words;if(!list.length){visit('map');return;}db.session={lesson:review?null:id,review,queue:buildQueue(list,review),index:0,correct:0,total:0,xp:0,retried:[],started:Date.now()};save();visit('lesson');}
function checkpoint(){save();}
function audioControls(w,big=false){return `<div class="audio-controls"><button class="audio-btn ${big?'big':''}" data-speak="${w.id}" aria-label="Послушать слово">${big?'◖))':'◖)) Слушать'}</button><button class="audio-btn" data-slow="${w.id}">Медленнее</button></div><div id="audio-error" class="audio-error" hidden>Звук не запустился. Проверь громкость и попробуй ещё раз.${view==='lesson'?'<br><button class="chip" data-action="text-mode">Продолжить с текстом</button>':''}</div>`;}
function getChoices(q){if(q.options)return q.options;const correct=byId[q.id],pool=lessons[correct.lesson].words;const rest=shuffle(pool.filter(w=>w.id!==correct.id));if(rest.length<3)rest.push(...shuffle(words.filter(w=>w.id!==correct.id&&!rest.some(r=>r.id===w.id))).slice(0,3-rest.length));q.options=shuffle([correct,...rest.slice(0,3)]).map(w=>w.id);return q.options;}
function renderTask(){const s=db.session;if(!s){visit('map');return;}if(s.index>=s.queue.length){finishSession();return;}const q=s.queue[s.index],w=byId[q.id],stage=q.mode==='learn'?'ЗНАКОМСТВО':q.mode==='recall'?'ВСПОМНИ САМ':q.mode==='listen'?'СЛУШАЙ И УЗНАВАЙ':'НАЙДИ ПЕРЕВОД';
const title=q.mode==='learn'?'Новое слово — новое открытие':q.mode==='listen'?'Что ты слышишь?':q.mode==='recall'?'Как это сказать по-английски?':'Что значит это слово?';
const help=q.mode==='learn'?'Послушай слово и повтори его вслух.':q.mode==='listen'?'Нажми на динамик, затем выбери перевод.':q.mode==='recall'?'Произнеси сам, затем послушай образец.':'Выбери подходящий перевод.';
main.innerHTML=`<div class="lesson-view"><div class="lesson-topbar"><button class="close" data-view="map" aria-label="Сохранить и выйти на карту">×</button><div class="bar" role="progressbar" aria-label="Прогресс занятия" aria-valuenow="${s.index}" aria-valuemin="0" aria-valuemax="${s.queue.length}"><i style="width:${s.index/s.queue.length*100}%"></i></div><span class="step-label">${s.index+1} / ${s.queue.length}</span></div><div class="eyebrow">${s.review?'ПОВТОРЕНИЕ':`ОСТРОВ ${s.lesson+1}`} · ${stage}</div><h1 class="task-title">${title}</h1><p class="task-help">${help}</p><div id="task"></div><div id="feedback" role="status" aria-live="polite"></div><div id="actions" class="lesson-actions"></div></div>`;
if(q.mode==='learn'){$('task').innerHTML=`<div class="flashcard"><span class="word-icon" aria-hidden="true">${w.icon}</span><span class="word-en" lang="en">${esc(w.en)}</span><span class="word-ru">${esc(w.ru)}</span>${audioControls(w)}</div>`;$('actions').innerHTML='<button class="btn green" data-action="next">Повторил, дальше →</button>';}
else if(q.mode==='recall'){$('task').innerHTML=`<div class="flashcard"><span class="word-icon" aria-hidden="true">${w.icon}</span><span class="word-ru" style="color:var(--ink);font-size:27px">${esc(w.ru)}</span><div id="recall-answer" ${q.revealed?'':'hidden'}><span class="word-en" lang="en">${esc(w.en)}</span>${audioControls(w)}</div></div>`;if(q.revealed)recallButtons();else $('actions').innerHTML='<button class="btn" data-action="reveal">Послушать и проверить</button>';}
else{let listening=q.mode==='listen';$('task').innerHTML=`<div class="flashcard" style="min-height:${listening?'180':'140'}px">${listening?audioControls(w,true):`<span class="word-en" lang="en">${esc(w.en)}</span>${audioControls(w)}`}</div><div class="choices">${getChoices(q).map(id=>`<button class="choice" data-choice="${id}" ${q.answered||listening&&!q.heard?'disabled':''}>${esc(byId[id].ru)}</button>`).join('')}</div>`;if(q.answered)showFeedback(q);}
save();}
function recallButtons(){$('actions').innerHTML='<button class="btn secondary" data-action="recall-again">Ещё потренирую</button><button class="btn green" data-action="recall-good">Вспомнил!</button>';}
function record(id,correct,mode){const t=stat(id),now=Date.now(),day=new Date(now).toLocaleDateString('en-CA');t.seen=Math.max(t.seen,1);t.last=now;if(correct){t.correct++;t.streak++;if(!t.modes.includes(mode))t.modes.push(mode);if(t.lastSuccessDay!==day||!t.box){t.box=Math.min((t.box||0)+1,3);t.lastSuccessDay=day;}t.due=now+[0,86400000,259200000,604800000][t.box];}else{t.errors++;t.streak=0;t.box=0;t.due=now;}return t;}
function answer(id){const s=db.session,q=s?.queue[s.index];if(!q||q.answered||q.mode==='listen'&&!q.heard)return;q.answered=true;q.selected=id;q.right=id===q.id;record(q.id,q.right,q.mode);s.total++;if(q.right){s.correct++;s.xp+=10;db.xp+=10;}else if(!s.retried.includes(q.id)){s.queue.push({id:q.id,mode:q.mode});s.retried.push(q.id);}save();document.querySelectorAll('.choice').forEach(b=>b.disabled=true);showFeedback(q);}
function showFeedback(q){document.querySelectorAll('.choice').forEach(b=>{b.classList.toggle('correct',b.dataset.choice===q.id);b.classList.toggle('wrong',!q.right&&b.dataset.choice===q.selected);});const w=byId[q.id];$('feedback').innerHTML=`<div class="feedback ${q.right?'':'warm'}"><strong>${q.right?'Верно! +10 XP':'Теперь знаем ответ!'}</strong><span lang="en">${esc(w.en)}</span> — ${esc(w.ru)}${q.right?'':'<br>Это слово ещё встретится в повторении.'}</div>`;$('actions').innerHTML='<button class="btn green" data-action="next">Дальше →</button>';}
function nextTask(){const s=db.session,q=s.queue[s.index];if(q.mode==='learn'){const t=stat(q.id);t.seen++;t.due=t.due||Date.now();}else if(['translate','listen'].includes(q.mode)&&!q.answered)return;stopSpeech();s.index++;save();renderTask();window.scrollTo({top:0,behavior:'instant'});}
function finishSession(){const s=db.session;if(!s)return;stopSpeech();const ratio=s.correct/Math.max(1,s.total),stars=ratio>=.85?3:ratio>=.6?2:1;const first=s.lesson!==null&&!db.done[s.lesson];if(s.lesson!==null)db.done[s.lesson]=Math.max(db.done[s.lesson]||0,stars);if(first){db.xp+=20;s.xp+=20;}const today=new Date().toLocaleDateString('en-CA');if(!db.days.includes(today))db.days.push(today);const xp=s.xp,id=s.lesson,review=s.review,correct=s.correct,total=s.total;db.session=null;save();view='result';main.innerHTML=`<div class="lesson-view result"><img src="dragon.png" alt="Драко радуется твоему успеху"><div class="reward" aria-label="${stars} звезды">${'★'.repeat(stars)}${'☆'.repeat(3-stars)}</div><h1>${review?'Слова стали ближе!':id===lessons.length-1?'Все занятия со словами пройдены!':'Ещё один остров открыт!'}</h1><p>${review?'Отличная тренировка.':`«${esc(lessons[id].title)}» пройден.`}<br>Правильных ответов: ${correct} из ${total} · +${xp} XP</p><div class="feedback">${id===lessons.length-1?'Ты прошёл все занятия со словами! Проверь себя в заданиях тематических островов. Возвращайся к словам в разделе «Повторение».':'Можно закончить на сегодня. Маленький шаг уже сделан!'}</div>${id!==null&&scopedLessons().findIndex(l=>l.id===id)<scopedLessons().length-1?`<button class="btn" data-lesson="${scopedLessons()[scopedLessons().findIndex(l=>l.id===id)+1]?.id}">Следующий остров →</button>`:''}<button class="btn secondary" data-view="map">Вернуться на карту</button></div>`;window.scrollTo({top:0,behavior:'instant'});}
document.addEventListener('click',e=>{const b=e.target.closest('button,a.logo');if(!b||b.disabled)return;if(b.matches('a.logo')){e.preventDefault();visit('map');return;}if(b.dataset.part){activePart=Number(b.dataset.part);save();activeTheme=null;quizState=null;stopSpeech();visit('map');return;}if(b.dataset.view){visit(b.dataset.view);return;}if(b.dataset.topic){activeTheme=themes.find(t=>t.id===b.dataset.topic);activePart=activeTheme.part;bookPage=bookPages[activeTheme.id][0];themeTab=b.dataset.openBook?'book':'study';quizState=null;visit('topic');return;}if(b.dataset.topicTab){stopSpeech();quizState=null;themeTab=b.dataset.topicTab;renderTheme();return;}if(b.dataset.example!==undefined){speakExample(Number(b.dataset.example),!!b.dataset.exampleSlow,b);return;}if(b.dataset.topicAnswer!==undefined){if(quizState.answers[quizState.index])return;submitTask(quizState.options[Number(b.dataset.topicAnswer)]);return;}if(b.dataset.topicNext){quizState.index++;for(const k of ['options','tokens','picked','draft','heard','textMode'])delete quizState[k];renderQuiz();return;}if(b.dataset.topicRetry){delete db.practiceSessions?.[`${activeTheme.id}:${themeTab}`];quizState=null;renderQuiz();return;}if(b.dataset.pick!==undefined){quizState.picked.push(Number(b.dataset.pick));renderQuiz();return;}if(b.dataset.unpick!==undefined){quizState.picked=quizState.picked.filter(id=>id!==Number(b.dataset.unpick));renderQuiz();return;}if(b.dataset.checkBuild){submitTask(quizState.picked.map(id=>quizState.tokens.find(t=>t.id===id).word).join(' '));return;}if(b.dataset.taskAudio){const q=currentTasks()[quizState.index];trainingSpeech(q.speech,b,b.dataset.taskAudio==='slow',()=>{quizState.heard=true;if($('written-check'))$('written-check').disabled=false;});return;}if(b.dataset.numberText){quizState.textMode=true;quizState.draft=$('written-answer').value;renderQuiz();return;}if(b.dataset.readingAudio){trainingSpeech(currentTasks()[quizState.index].text,b);return;}if(b.dataset.answerAudio){trainingSpeech(currentTasks()[quizState.index].answer,b);return;}if(b.dataset.bookPage){bookPage=Number(b.dataset.bookPage);renderBook();return;}if(b.dataset.bookStep){bookPage+=Number(b.dataset.bookStep);renderBook();return;}if(b.dataset.bookSave){saveBook();return;}if(b.dataset.bookRead){trainingSpeech($('book-answer').value,b);return;}if(b.dataset.lesson!==undefined){begin(Number(b.dataset.lesson));return;}if(b.dataset.speak){speak(b.dataset.speak,false,b);return;}if(b.dataset.slow){speak(b.dataset.slow,true,b);return;}if(b.dataset.filter){filter=b.dataset.filter;renderDictionary();return;}if(b.dataset.choice){answer(b.dataset.choice);return;}const action=b.dataset.action;if(action==='continue'){if(db.session){const current=themes.find(t=>t.ids.includes(db.session.lesson));if(current)activePart=current.part;visit('lesson');}else begin(nextLesson().id);}if(action==='review')begin(0,true);if(action==='next')nextTask();if(action==='reveal'){const q=db.session.queue[db.session.index];q.revealed=true;$('recall-answer').hidden=false;recallButtons();save();speak(q.id);}if(action==='recall-good'||action==='recall-again'){const q=db.session.queue[db.session.index];if(action==='recall-again'){const t=stat(q.id);t.due=Date.now();t.streak=0;}nextTask();}if(action==='text-mode'){const q=db.session.queue[db.session.index];if(q.mode==='listen'){q.mode='translate';q.heard=false;renderTask();toast('Продолжаем с текстом. Звук можно настроить в разделе для родителей.');}else{$('audio-error').hidden=true;toast('Можно продолжить с текстом и вернуться к озвучке позже.');}}});
document.addEventListener('visibilitychange',()=>{if(document.hidden){stopSpeech();if(db.session)save();}});visit('map');

function saveBook(){const exercise=$('exercise-number').value.trim(),text=$('book-answer').value.trim();if(!exercise||!text){toast('Укажи номер задания и напиши ответ.');return;}db.notebook??={};db.bookAnswers??={};db.notebook[pageKey()]={exercise,text};db.bookAnswers[`${pageKey()}:${exercise}`]={exercise,text};save();$('book-save-status').textContent='Ответ сохранён на этом устройстве.';}
document.addEventListener('submit',e=>{if(e.target.id==='written-task'){e.preventDefault();const value=$('written-answer').value;const q=currentTasks()[quizState.index];if(q.kind==='free'&&value.trim()){db.writtenWorks??={};db.writtenWorks[`${activeTheme.id}:${quizState.index}`]=value;save();}submitTask(value,q.kind==='free');}});
document.addEventListener('change',e=>{if(e.target.id==='book-page'){bookPage=Number(e.target.value);renderBook();}});
document.addEventListener('input',e=>{if(e.target.id==='written-answer'&&quizState){quizState.draft=e.target.value;save();}});
document.addEventListener('change',e=>{if(e.target.id==='exercise-number'){const saved=db.bookAnswers?.[`${pageKey()}:${e.target.value.trim()}`];$('book-answer').value=saved?.text||'';}});
